function setInput(k,v){if(k in keys)keys[k]=v}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();let key=null;if(['arrowleft','a'].includes(k))key='left';if(['arrowright','d'].includes(k))key='right';if(['arrowup','w',' '].includes(k))key='jump';if(['shift','x'].includes(k))key='dash';if(key){e.preventDefault();setInput(key,true)}if(k==='p'||k==='escape'){e.preventDefault();if(state.mode==='play')pause();else if(state.mode==='pause'){state.mode='play';hideOverlay()}}if(k==='enter'&&state.mode==='menu'){startRun(0,true)}});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(['arrowleft','a'].includes(k))setInput('left',false);if(['arrowright','d'].includes(k))setInput('right',false);if(['arrowup','w',' '].includes(k))setInput('jump',false);if(['shift','x'].includes(k))setInput('dash',false)});window.addEventListener('blur',()=>{for(const k in keys)keys[k]=false;if(state.mode==='play')pause()});
for(const touch of document.querySelectorAll('[data-key]')){const name=touch.dataset.key;const press=e=>{e.preventDefault();touch.classList.add('pressed');setInput(name,true)},release=e=>{e.preventDefault();touch.classList.remove('pressed');setInput(name,false)};touch.addEventListener('pointerdown',e=>{touch.setPointerCapture(e.pointerId);press(e)});touch.addEventListener('pointerup',release);touch.addEventListener('pointercancel',release);touch.addEventListener('lostpointercapture',release)}
overlay.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;beep(600,.06,'triangle',.025);if(a==='start')startRun(0,true);else if(a==='menu')mainMenu();else if(a==='help')help();else if(a==='levels')levels();else if(a==='next')loadLevel(Math.min(3,state.level+1));else if(a==='retry'){state.lives=3;loadLevel(state.level)}else if(a==='restart')loadLevel(state.level);else if(a==='resume'){state.mode='play';hideOverlay()}else if(a.startsWith('level-')){const n=Number(a.slice(6));if(n<=state.unlocked)startRun(n,true)}else if(a.startsWith('interview-'))interview(Number(a.slice(10)))});
